import cv2, numpy as np
im=cv2.imread('first_frame.png')
g=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY)
for mode in range(3):
 e=cv2.Canny(g,20+mode*30,60+mode*60)
 lines=cv2.HoughLinesP(e,1,np.pi/180,threshold=10,minLineLength=7,maxLineGap=3)
 print('mode',mode)
 if lines is not None:
  for l in lines[:,0]:
   x1,y1,x2,y2=map(int,l)
   if 130<x1<256 and 20<y1<110 and 130<x2<256 and 20<y2<110:
    print(l.tolist(), 'len',round(np.hypot(x2-x1,y2-y1),1),'angle',round(np.degrees(np.arctan2(y2-y1,x2-x1)),1))
# output run-length of pixels dark per rows and salient high sat per rows in region
rgb=im[:,:,::-1]
mx=rgb.max(2); mn=rgb.min(2)
sat=mx-mn
for y in range(25,105):
 vals=[]
